+	int counter, retcode;
+	
+	if (msgc < 1 || msgv == NULL || request == NULL) {
+		return PAM_CONV_ERR;
+	}
+	*rspv = malloc(msgc * sizeof(struct pam_response));
+	if (*rspv == NULL) {
+		return PAM_CONV_ERR;
+	}
+	
+	memset(*rspv, 0, msgc * sizeof(struct pam_response));
+	retcode = PAM_SUCCESS;
+	
